import React, { useState } from "react";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { storage } from "../firebase";
import Button from "react-bootstrap/Button";
import Form from "react-bootstrap/Form";
import toast from "react-hot-toast";

const UploadAllegati = ({ interventoId, statoTecnico }) => {
  const [files, setFiles] = useState([]);
  const [preview, setPreview] = useState([]);

  if (!["attesa_ricambi", "conclusa"].includes(statoTecnico)) return null;

  const handleFileChange = (e) => {
    const selected = Array.from(e.target.files);
    setFiles(selected);

    const previews = selected.map((file) => URL.createObjectURL(file));
    setPreview(previews);
  };

  const handleUpload = async () => {
    if (files.length === 0) return toast.error("❌ Nessun file selezionato");

    toast.loading("📤 Caricamento in corso...");

    try {
      for (const file of files) {
        const fileRef = ref(storage, `allegati/${interventoId}/${file.name}`);
        await uploadBytes(fileRef, file);
        const url = await getDownloadURL(fileRef);
        console.log("✅ File caricato:", url);
        // Puoi salvare l'URL nel documento Firestore se necessario
      }

      toast.dismiss();
      toast.success("✅ Tutti i file caricati");
      setFiles([]);
      setPreview([]);
    } catch (error) {
      console.error("Errore upload:", error);
      toast.dismiss();
      toast.error("❌ Errore durante il caricamento");
    }
  };

  return (
    <Form className="mt-3">
      <Form.Group controlId="formFileMultiple">
        <Form.Label>📎 Allega foto o file</Form.Label>
        <Form.Control
          type="file"
          multiple
          accept="image/*"
          capture="environment"
          onChange={handleFileChange}
        />
      </Form.Group>

      <div className="d-flex flex-wrap gap-2 mt-3">
        {preview.map((src, index) => (
          <img
            key={index}
            src={src}
            alt={`preview-${index}`}
            style={{ height: "80px", borderRadius: "6px", boxShadow: "0 0 4px rgba(0,0,0,0.2)" }}
          />
        ))}
      </div>

      <Button variant="success" className="mt-3" onClick={handleUpload}>
        📤 Carica {files.length > 1 ? "allegati" : "allegato"}
      </Button>
    </Form>
  );
};

export default UploadAllegati;