import Button from "react-bootstrap/Button";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../firebase";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction";

const CalendarioInterventiProgrammati = () => {
  const [eventi, setEventi] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchInterventi = async () => {
      const snapshot = await getDocs(collection(db, "INTERVENTI"));
      const lista = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));

      const programmati = lista.filter(
        (i) =>
          i.categoria === "Manutenzione Programmata" &&
          i.dataIntervento &&
          i.frequenza &&
          i.ragioneSociale
      );

      const eventiCalendario = programmati.map((i) => {
        const baseDate = i.dataIntervento.toDate();
        let prossima = new Date(baseDate);

        if (i.frequenza === "trimestrale") {
          prossima.setMonth(prossima.getMonth() + 3);
        } else if (i.frequenza === "annuale") {
          prossima.setFullYear(prossima.getFullYear() + 1);
        }

        return {
          id: i.id,
          title: `${i.ragioneSociale} (${i.frequenza})`,
          start: prossima.toISOString().split("T")[0],
          allDay: true
        };
      });

      setEventi(eventiCalendario);
    };

    fetchInterventi();
  }, []);

  return (
    <div className="mt-4">
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h4>📅 Calendario Manutenzioni Programmate</h4>
        <Button variant="secondary" onClick={() => navigate("/")}>
          ⬅️ Indietro alla Dashboard
        </Button>
      </div>

      <FullCalendar
        plugins={[dayGridPlugin, interactionPlugin]}
        initialView="dayGridMonth"
        events={eventi}
        height="auto"
        headerToolbar={{
          left: "prev,next today",
          center: "title",
          right: "dayGridMonth,dayGridWeek"
        }}
      />
    </div>
  );
};

export default CalendarioInterventiProgrammati;