import React from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import MarkerClusterGroup from "react-leaflet-cluster";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

// Fix icona marker Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

const MappaClienti = ({ clienti }) => {
  // ✅ Protezione contro undefined o dati malformati
  const clientiConCoordinate = Array.isArray(clienti)
    ? clienti.filter(
        (c) =>
          typeof c.lat === "number" &&
          typeof c.lng === "number" &&
          !isNaN(c.lat) &&
          !isNaN(c.lng)
      )
    : [];

  if (clientiConCoordinate.length === 0) {
    return (
      <div className="text-muted mt-3">
        ⚠️ Nessun cliente con coordinate valide da visualizzare.
      </div>
    );
  }

  return (
    <MapContainer
      center={[44.7, 10.6]}
      zoom={8}
      style={{ height: "500px", width: "100%" }}
      scrollWheelZoom={true}
    >
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="© OpenStreetMap contributors"
      />
      <MarkerClusterGroup>
        {clientiConCoordinate.map((c, i) => (
          <Marker key={i} position={[c.lat, c.lng]}>
            <Popup>
              <strong>{c.ragioneSociale || "Cliente"}</strong><br />
              {c.indirizzo || "Indirizzo non disponibile"}, {c.cap || ""} {c.comune || ""} ({c.provincia || ""})<br />
              Urgenza: <strong>{c.urgenza || "media"}</strong>
            </Popup>
          </Marker>
        ))}
      </MarkerClusterGroup>
    </MapContainer>
  );
};

export default MappaClienti;