import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import MarkerCluster from "react-leaflet-cluster";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../firebase";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import "react-leaflet-cluster/dist/assets/MarkerCluster.css";
import "react-leaflet-cluster/dist/assets/MarkerCluster.Default.css";
import "./MappaClienti.css"; // opzionale per stile personalizzato

// ✅ Configura icona marker
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
  iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
  shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
});

const MappaClienti = () => {
  const [clienti, setClienti] = useState([]);
  const [errore, setErrore] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const lista = snapshot.docs
          .map((doc) => ({ id: doc.id, ...doc.data() }))
          .filter((c) => c.latitudine && c.longitudine);
        setClienti(lista);
      } catch (error) {
        console.error("Errore nel caricamento clienti:", error);
        setErrore("❌ Errore nel caricamento clienti.");
      } finally {
        setLoading(false);
      }
    };

    fetchClienti();
  }, []);

  const centroMappa = clienti.length > 0
    ? [clienti[0].latitudine, clienti[0].longitudine]
    : [44.697, 10.788]; // fallback: Correggio

  return (
    <div className="mappa-clienti-container p-3">
      <h4 className="mb-3">🗺️ Mappa Clienti Geolocalizzati</h4>

      {errore && <p className="text-danger">{errore}</p>}
      {loading && <p className="text-muted">🔄 Caricamento mappa...</p>}

      <MapContainer center={centroMappa} zoom={7} style={{ height: "600px", width: "100%" }}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/">OpenStreetMap</a>'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        <MarkerCluster>
          {clienti.map((c) => (
            <Marker key={c.id} position={[c.latitudine, c.longitudine]}>
              <Popup>
                <strong>{c.ragioneSociale || "Cliente"}</strong><br />
                {c.indirizzo || "Indirizzo non disponibile"}
              </Popup>
            </Marker>
          ))}
        </MarkerCluster>
      </MapContainer>
    </div>
  );
};

export default MappaClienti;