import React, { useEffect, useState } from "react";
import {
  collection,
  onSnapshot,
  getDoc,
  getDocs,
  query,
  where,
  doc,
  deleteDoc,
  addDoc,
  updateDoc,
  Timestamp,
} from "firebase/firestore";
import { db } from "./firebase";
import { useAuth } from "./AuthContext";
import Container from "react-bootstrap/Container";
import Table from "react-bootstrap/Table";
import Form from "react-bootstrap/Form";
import Alert from "react-bootstrap/Alert";
import Spinner from "react-bootstrap/Spinner";
import Button from "react-bootstrap/Button";
import toast from "react-hot-toast";
import NotifichePanel from "./NotifichePanel";
import CsvUploader from "./CsvUploader";
import NuovaChiamataForm from "./NuovaChiamataForm";
import MappaClienti from "./MappaClienti";
import StatisticheInterventi from "./components/StatisticheInterventi";
import UploadAllegati from "./components/UploadAllegati";
import CalendarioInterventi from "./components/CalendarioInterventi";
import CreaUtenteForm from "./components/CreaUtenteForm";
import { normalizzaEGeolocalizzaClienti } from "./utils/normalizzaEGeolocalizzaClienti";

const DashboardAdmin = () => {
  const { ruolo, user } = useAuth();
  const [interventi, setInterventi] = useState([]);
  const [mezzi, setMezzi] = useState({});
  const [tecnici, setTecnici] = useState([]);
  const [filtroStato, setFiltroStato] = useState("");
  const [loading, setLoading] = useState(true);
  const [errore, setErrore] = useState("");

  useEffect(() => {
    const unsubscribe = onSnapshot(collection(db, "INTERVENTI"), async (snapshot) => {
      try {
        const lista = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
        const mezzoIds = [...new Set(lista.map((i) => i.mezzoId).filter(Boolean))];
        const mezzoData = {};

        for (const id of mezzoIds) {
          const ref = doc(db, "MEZZI", id);
          const snap = await getDoc(ref);
          if (snap.exists()) mezzoData[id] = snap.data();
        }

        setMezzi(mezzoData);
        setInterventi(lista);
        setLoading(false);
      } catch (error) {
        console.error("Errore nel caricamento interventi:", error);
        setErrore("❌ Errore nel caricamento interventi.");
        setLoading(false);
      }
    });

    const fetchTecnici = async () => {
      try {
        const snapshot = await getDocs(
          query(collection(db, "UTENTI"), where("ruolo", "==", "tecnico"))
        );
        const lista = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setTecnici(lista);
      } catch (error) {
        console.error("Errore nel caricamento tecnici:", error);
      }
    };

    fetchTecnici();
    return () => unsubscribe();
  }, []);

  const logAttività = async (azione, dettaglio) => {
    try {
      await addDoc(collection(db, "LOG_ATTIVITA"), {
        utente: user?.email || "sconosciuto",
        ruolo,
        azione,
        dettaglio,
        timestamp: Timestamp.now(),
      });
    } catch (error) {
      console.warn("⚠️ Errore nel log attività:", error.message);
    }
  };

  const eliminaIntervento = async (id) => {
    const conferma = window.confirm("Sei sicuro di voler eliminare questo intervento?");
    if (!conferma) return;

    try {
      await deleteDoc(doc(db, "INTERVENTI", id));
      toast.success("✅ Intervento eliminato");
      await logAttività("Eliminazione intervento", `ID: ${id}`);
    } catch (error) {
      console.error("Errore eliminazione:", error);
      toast.error("❌ Errore durante l'eliminazione");
    }
  };

  const terminaIntervento = async (id) => {
    try {
      await updateDoc(doc(db, "INTERVENTI", id), { terminato: true });
      toast.success("✅ Intervento terminato");
      await logAttività("Intervento terminato", `ID: ${id}`);
    } catch (error) {
      console.error("Errore aggiornamento:", error);
      toast.error("❌ Errore durante la chiusura");
    }
  };

  const aggiornaTecnico = async (id, tecnicoId) => {
    try {
      await updateDoc(doc(db, "INTERVENTI", id), {
        tecnicoAssegnatoId: tecnicoId,
      });
      toast.success("👨‍🔧 Tecnico assegnato");
    } catch (error) {
      toast.error("❌ Errore assegnazione tecnico");
    }
  };

  const aggiornaStatoTecnico = async (id, nuovoStato) => {
    try {
      await updateDoc(doc(db, "INTERVENTI", id), {
        statoTecnico: nuovoStato,
      });
      toast.success("🔄 Stato aggiornato");
    } catch (error) {
      toast.error("❌ Errore aggiornamento stato");
    }
  };

  const geolocalizzaClienti = async () => {
    toast.loading("📍 Geolocalizzazione in corso...");
    try {
      await normalizzaEGeolocalizzaClienti();
      toast.dismiss();
      toast.success("📍 Geolocalizzazione completata");
      await logAttività("Geolocalizzazione clienti", "Eseguita da admin");
    } catch (error) {
      toast.dismiss();
      toast.error("❌ Errore durante la geolocalizzazione");
    }
  };

  const filtrati = filtroStato
    ? interventi.filter((i) => i.statoTecnico === filtroStato)
    : interventi;

  const oggi = new Date();
  const alertInterventi = interventi.filter((i) => {
    if (
      i.categoria !== "Manutenzione Programmata" ||
      !i.prossimoIntervento ||
      i.terminato
    )
      return false;

    const dataProssima = i.prossimoIntervento.toDate();
    const diff = (dataProssima - oggi) / (1000 * 60 * 60 * 24);
    return diff <= 7 && diff >= 0;
  });

  return (
    <Container className="mt-4">
      <h3 className="mb-4">📊 Dashboard Amministratore</h3>

      {errore && <Alert variant="danger">{errore}</Alert>}

      {alertInterventi.length > 0 && (
        <Alert variant="warning">
          <strong>🔔 Manutenzioni in scadenza:</strong>
          <ul className="mt-2">
            {alertInterventi.map((i) => (
              <li key={i.id}>
                {i.ragioneSociale} - {i.categoria} -{" "}
                {i.prossimoIntervento.toDate().toLocaleDateString()}
                <Button
                  variant="outline-success"
                  size="sm"
                  className="ms-2"
                  onClick={() => terminaIntervento(i.id)}
                >
                  ✅ Termina
                </Button>
              </li>
            ))}
          </ul>
        </Alert>
      )}

      <Form.Select
        value={filtroStato}
        onChange={(e) => setFiltroStato(e.target.value)}
        style={{ maxWidth: "300px", marginBottom: "1rem" }}
      >
        <option value="">🔍 Filtra per stato tecnico</option>
        <option value="assegnato">Assegnato</option>
        <option value="accettata">Accettata</option>
        <option value="attesa_ricambi">In attesa ricambi</option>
        <option value="conclusa">Conclusa</option>
      </Form.Select>
            {loading ? (
        <div className="text-center my-5">
          <Spinner animation="border" variant="primary" />
          <p className="mt-3 text-muted">Caricamento interventi...</p>
        </div>
      ) : (
        <Table striped bordered hover responsive>
          <thead>
            <tr>
              <th>Cliente</th>
              <th>Mezzo</th>
              <th>Categoria</th>
              <th>Data</th>
              <th>Tecnico</th>
              <th>Stato tecnico</th>
              <th>Note tecnico + Allegati</th>
              {ruolo === "admin" && <th>Azioni</th>}
            </tr>
          </thead>
          <tbody>
            {filtrati.map((i) => {
              const mezzo = mezzi[i.mezzoId];
              const data = i.dataIntervento?.seconds
                ? new Date(i.dataIntervento.seconds * 1000).toLocaleDateString()
                : "—";
              return (
                <tr key={i.id}>
                  <td>{i.ragioneSociale || "—"}</td>
                  <td>{mezzo ? `${mezzo.marca} ${mezzo.modello}` : "—"}</td>
                  <td>{i.categoria || "—"}</td>
                  <td>{data}</td>
                  <td>
                    <Form.Select
                      size="sm"
                      value={i.tecnicoAssegnatoId || ""}
                      onChange={(e) => aggiornaTecnico(i.id, e.target.value)}
                    >
                      <option value="">—</option>
                      {tecnici.map((t) => (
                        <option key={t.id} value={t.id}>
                          {t.nome || t.email}
                        </option>
                      ))}
                    </Form.Select>
                  </td>
                  <td>
                    <Form.Select
                      size="sm"
                      value={i.statoTecnico || ""}
                      onChange={(e) => aggiornaStatoTecnico(i.id, e.target.value)}
                    >
                      <option value="">—</option>
                      <option value="assegnato">Assegnato</option>
                      <option value="accettata">Accettata</option>
                      <option value="attesa_ricambi">In attesa ricambi</option>
                      <option value="conclusa">Conclusa</option>
                    </Form.Select>
                  </td>
                  <td>
                    {i.noteTecnico || "—"}
                    <UploadAllegati
                      interventoId={i.id}
                      statoTecnico={i.statoTecnico}
                    />
                  </td>
                  {ruolo === "admin" && (
                    <td>
                      <Button
                        variant="danger"
                        size="sm"
                        onClick={() => eliminaIntervento(i.id)}
                      >
                        🗑️ Elimina
                      </Button>
                    </td>
                  )}
                </tr>
              );
            })}
          </tbody>
        </Table>
      )}

      <div className="mt-5">
        <NotifichePanel />
      </div>

      <div className="mt-5">
        <NuovaChiamataForm />
      </div>

      <div className="mt-5">
        <MappaClienti />
      </div>

      <div className="mt-5">
        <StatisticheInterventi />
      </div>

      <div className="mt-5">
        <CalendarioInterventi />
      </div>

      <div className="mt-5 d-flex flex-column gap-3">
        <CsvUploader titolo="📥 Importa Clienti" collezione="CLIENTI" />
        <CsvUploader titolo="📥 Importa Mezzi" collezione="MEZZI" />
        {ruolo === "admin" && (
          <>
            <Button variant="info" onClick={geolocalizzaClienti}>
              📍 Geolocalizza Clienti
            </Button>

            <div className="mt-4">
              <CreaUtenteForm />
            </div>
          </>
        )}
      </div>
    </Container>
  );
};

export default DashboardAdmin;