import React, { useEffect, useState } from "react";
import { collection, getDocs, updateDoc, doc } from "firebase/firestore";
import { db } from "./firebase";
import { normalizzaUtente } from "./utils/normalizza";
import DateDisplay from "./components/DateDisplay";
import CreaUtenteForm from "./components/CreaUtenteForm";
import Spinner from "react-bootstrap/Spinner";
import Button from "react-bootstrap/Button";
import { CSVLink } from "react-csv";
import * as XLSX from "xlsx";

function DashboardUtenti() {
  const [utenti, setUtenti] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUtenti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "UTENTI"));
        const dati = snapshot.docs.map(d => ({
          id: d.id,
          ...normalizzaUtente(d.data())
        }));
        setUtenti(dati);
      } catch (error) {
        console.error("Errore nel recupero utenti:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchUtenti();
  }, []);

  const disattivaUtente = async (id) => {
    const conferma = window.confirm("Vuoi disattivare questo utente?");
    if (!conferma) return;
    try {
      await updateDoc(doc(db, "UTENTI", id), { attivo: false });
      setUtenti(prev => prev.map(u => u.id === id ? { ...u, attivo: false } : u));
    } catch (error) {
      console.error("Errore disattivazione:", error);
    }
  };

  const totali = {
    admin: utenti.filter(u => u.ruolo === "admin").length,
    tecnico: utenti.filter(u => u.ruolo === "tecnico").length,
    cliente: utenti.filter(u => u.ruolo === "cliente").length,
    attivi: utenti.filter(u => u.attivo).length,
    disattivi: utenti.filter(u => !u.attivo).length
  };

  const ultimi = [...utenti]
    .sort((a, b) => (b.dataCreazione?.seconds || 0) - (a.dataCreazione?.seconds || 0))
    .slice(0, 5);

  const intestazioniCSV = [
    { label: "Nome", key: "nome" },
    { label: "Email", key: "email" },
    { label: "Ruolo", key: "ruolo" },
    { label: "Attivo", key: "attivo" },
    { label: "Data Creazione", key: "dataCreazione" }
  ];

  const esportaExcel = () => {
    const dati = utenti.map(u => ({
      Nome: u.nome,
      Email: u.email,
      Ruolo: u.ruolo,
      Attivo: u.attivo ? "Sì" : "No",
      Data: u.dataCreazione?.seconds
        ? new Date(u.dataCreazione.seconds * 1000).toLocaleDateString()
        : "—"
    }));
    const ws = XLSX.utils.json_to_sheet(dati);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Utenti");
    XLSX.writeFile(wb, "utenti.xlsx");
  };

  return (
    <div className="container mt-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h3>📊 Dashboard Utenti</h3>
        <div className="d-flex gap-2">
          <CSVLink
            data={utenti}
            headers={intestazioniCSV}
            filename="utenti.csv"
            className="btn btn-outline-primary btn-sm"
          >
            📤 CSV
          </CSVLink>
          <Button variant="outline-success" size="sm" onClick={esportaExcel}>
            📊 Excel
          </Button>
        </div>
      </div>

      {loading ? (
        <div className="text-center my-5">
          <Spinner animation="border" variant="primary" />
          <p className="mt-3 text-muted">Caricamento utenti...</p>
        </div>
      ) : (
        <>
          <div className="row mb-4">
            {Object.entries(totali).map(([key, value]) => (
              <div className="col" key={key}>
                <div className="card p-3 text-center shadow-sm">
                  <h5>
                    {key === "admin"
                      ? "Admin"
                      : key === "tecnico"
                      ? "Tecnici"
                      : key === "cliente"
                      ? "Clienti"
                      : key === "attivi"
                      ? "Attivi"
                      : "Disattivi"}
                  </h5>
                  <p
                    className={`display-6 ${
                      key === "attivi"
                        ? "text-success"
                        : key === "disattivi"
                        ? "text-danger"
                        : ""
                    }`}
                  >
                    {value}
                  </p>
                </div>
              </div>
            ))}
          </div>

          <h5 className="mt-4 mb-3">🕒 Ultimi utenti registrati</h5>
          <table className="table table-sm table-bordered table-hover">
            <thead className="table-light">
              <tr>
                <th>Nome</th>
                <th>Email</th>
                <th>Ruolo</th>
                <th>Stato</th>
                <th>Data</th>
                <th>Azioni</th>
              </tr>
            </thead>
            <tbody>
              {ultimi.map((u, i) => (
                <tr key={i}>
                  <td>{u.nome || "—"}</td>
                  <td>{u.email || "—"}</td>
                  <td>{u.ruolo || "—"}</td>
                  <td>{u.attivo ? "✅" : "⛔"}</td>
                  <td><DateDisplay data={u.dataCreazione} /></td>
                  <td>
                    {u.attivo && (
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => disattivaUtente(u.id)}
                      >
                        Disattiva
                      </Button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          <CreaUtenteForm />
        </>
      )}
    </div>
  );
}

export default DashboardUtenti;