import React, { useState, useEffect } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../firebase";
import Form from "react-bootstrap/Form";
import ListGroup from "react-bootstrap/ListGroup";

const AutocompleteClienti = ({ onSelect }) => {
  const [input, setInput] = useState("");
  const [suggerimenti, setSuggerimenti] = useState([]);

  useEffect(() => {
    const fetchClienti = async () => {
      if (input.length < 2) {
        setSuggerimenti([]);
        return;
      }

      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const tuttiClienti = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        const filtrati = tuttiClienti.filter((cliente) =>
          cliente.ragioneSociale?.toLowerCase().includes(input.toLowerCase())
        );

        setSuggerimenti(filtrati);
      } catch (error) {
        console.error("Errore ricerca clienti:", error);
        setSuggerimenti([]);
      }
    };

    fetchClienti();
  }, [input]);

  const handleSelect = (cliente) => {
    onSelect(cliente);
    setInput(cliente.ragioneSociale);
    setSuggerimenti([]);
  };

  return (
    <div>
      <Form.Control
        type="text"
        placeholder="🔍 Cerca cliente"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        autoComplete="off"
      />

      {suggerimenti.length > 0 && (
        <ListGroup className="mt-2">
          {suggerimenti.map((cliente) => (
            <ListGroup.Item
              key={cliente.id}
              action
              onClick={() => handleSelect(cliente)}
            >
              <strong>{cliente.ragioneSociale}</strong>
              {cliente.codiceInterno && (
                <span className="text-muted ms-2">
                  ({cliente.codiceInterno})
                </span>
              )}
            </ListGroup.Item>
          ))}
        </ListGroup>
      )}
    </div>
  );
};

export default AutocompleteClienti;