import React from "react";
import { Button } from "react-bootstrap";

/**
 * Esporta un array di oggetti in formato CSV.
 * @param {Array} dati - Array di oggetti da esportare
 * @param {string} nomeFile - Nome del file CSV
 * @param {string} separatore - Separatore CSV (default: ",")
 */
const EsportaCSV = ({ dati, nomeFile = "report_interventi.csv", separatore = "," }) => {
  const esporta = () => {
    if (!Array.isArray(dati) || dati.length === 0) {
      alert("⚠️ Nessun dato da esportare.");
      return;
    }

    const intestazioni = Object.keys(dati[0]);
    const righe = dati.map(row =>
      intestazioni.map(col => {
        const cella = row[col] ?? "";
        return `"${cella.toString().replace(/"/g, '""')}"`;
      }).join(separatore)
    );

    const csv = [intestazioni.join(separatore), ...righe].join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.setAttribute("download", nomeFile);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <Button variant="success" onClick={esporta}>
      📤 Esporta CSV
    </Button>
  );
};

export default EsportaCSV;